sys_ui_page.client_script:
// 生成PDF
function generatePDF() {
    var ga = new GlideAjax('GeneratePDF');
	// 执行Ajax生成PDF的方法
    ga.addParam('sysparm_name', 'generate');
    ga.getXMLAnswer(function(answer) {
        var srtJson = JSON.parse(answer);
        var attachmentId = srtJson.attachment.attachment_id;
		// 成功时
        if (srtJson.attachment.status === "success") {
            alert("success");
            var files = srtJson.filesUploaded;
            var message = "";
            var ele = document.getElementById('attachments_uploaded');
			// 生成下载Link，表示在画面上
            if (files != "") {
                files.forEach(function(fName) {
                    message += "<a href =" + fName.link + " >" + fName.file_name + "</a>" + "<br/>";
                });
            }
            ele.innerHTML = message;
        } else {
			// 生成时，提示信息
            alert('生成失败，请检查 PDF 配置。');
        }
    });
}

// 更新Field
function showConfirm() {
    if (confirm("Are you sure you want to update the field?")) {
		// 取得画面上的short description的值
		var sd = document.getElementById("sd").value;
        // 用户点击 OK
        var ga = new GlideAjax('UpdateFieldAjax');
        ga.addParam('sysparm_name', 'updateField');
		ga.addParam('sysparm_sd', sd);
        ga.addParam('sysparm_sys_id', '57af7aec73d423002728660c4cf6a71c'); 
        //ga.getXMLAnswer(function(response) {
		ga.getXML(function(response) {
            var answer = response.responseXML.documentElement.getAttribute("answer");
            if (answer === 'success') {
                alert('Field updated!');
                //location.reload(); // 或 g_form.refresh()
            } else {
                alert('Update failed.');
            }
        });
    } else {
        // 用户点击 Cancel
        alert("Update canceled.");
    }
}
